import type { SourceCell } from "@/games/wow-forever/data/spotDecode";

/**
 * `data/professions/crafting/classic/skinning.json` — GENERATED by
 * `python -m scripts.wow_professions.build` from cmangos classic-db (GPL-3.0):
 * Classic mob levels, spawns and skins that may differ in Forever.
 */
export interface SkinningFile {
  source: string;
  /** `["name", "minLevel", "maxLevel", "spawns", "zone", "subzone", "x", "y", "leather"]`. */
  mobColumns: readonly string[];
  /** One row per mob per zone it has a pack in, at its densest pack there. */
  mobs: readonly (readonly SourceCell[])[];
  /** `["minLevel", "maxLevel", "leathers"]`. */
  leatherColumns: readonly string[];
  /** What a mob of each level skins into, main leather first: `[minLevel, maxLevel, leathers]`. */
  leather: readonly (readonly (number | readonly string[])[])[];
  /** Item id of every leather the rows name, by name. */
  leatherIds: Readonly<Record<string, number>>;
  zones: Readonly<Record<string, string>>;
  /** Zone id -> "alliance" / "horde" / "contested". */
  territory: Readonly<Record<string, string>>;
}
